import java.io.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream in = System.in;

    static int read() throws IOException {
        if (ptr == len) { len = in.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != '-' && (c < '0' || c > '9')) c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + c - '0'; c = read(); }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException { return (int) nextLong(); }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), m = nextInt(), journeys = nextInt();
        long[] c2d = new long[n], d2c = new long[m];
        for (int i = 0; i < n; i++) c2d[i] = nextLong();
        for (int i = 0; i < m; i++) d2c[i] = nextLong();
        long t = 0;
        int a = 0, b = 0;
        for (int j = 0; j < journeys; j++) {
            while (a < n && c2d[a] < t) a++;
            if (a == n) { System.out.println(-1); return; }
            t = c2d[a++] + 100;
            while (b < m && d2c[b] < t) b++;
            if (b == m) { System.out.println(-1); return; }
            t = d2c[b++] + 100;
        }
        System.out.println(t);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	n := 0
	c, _ := rd.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' {
		c, _ = rd.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = rd.ReadByte()
	}
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = rd.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}

func main() {
	n, m, journeys := readInt(), readInt(), readInt()
	c2d := make([]int, n)
	d2c := make([]int, m)
